import sys

data = sys.stdin.read().split()
n, S = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
cnt = 0
for i in range(n):
    for j in range(i + 1, n):
        if abs(a[i] - a[j]) + abs(a[i] + a[j]) == S:
            cnt += 1
print(cnt)

